"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["25033"],{97158(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.banca.etapa_com_banca_da_segunda_instancia_sem_recurso_para_julgar","status":422,"titulo":"A etapa prev\xea banca que julga o recurso em 2\xaa inst\xe2ncia, e nenhum recurso da etapa admite inst\xe2ncia superior"},"descricao":{"codigo":"uniplus.selecao.banca.etapa_com_banca_da_segunda_instancia_sem_recurso_para_julgar","requisitos":["UNI-REQ-0454","UNI-REQ-0491"],"oQueAconteceu":["A etapa prev\xea uma banca com o papel de julgar o recurso em 2\xaa inst\xe2ncia, e nenhum recurso da pr\xf3pria etapa admite inst\xe2ncia superior (UNI-REQ-0491). A banca de 2\xaa inst\xe2ncia da etapa julga s\xf3 os recursos dela; o recurso da fase \xe9 julgado pela banca da pr\xf3pria fase. Por isso o recurso da fase admitir inst\xe2ncia superior n\xe3o justifica a banca da etapa.","O rascunho do processo aceita essa banca, porque \xe9 montado aos poucos. A recusa sai na publica\xe7\xe3o e na retifica\xe7\xe3o em ato \xfanico, uma por banca, como o c\xf3digo desta p\xe1gina no corpo da resposta, e n\xe3o na lista `errors[]`. O campo \xe9 `etapas[i].bancas[p]`, em que `i` \xe9 a posi\xe7\xe3o da etapa e `p`, a da banca, e a resposta traz a identifica\xe7\xe3o da etapa e a da banca em `identificadores`. Nesse lugar, a recusa de [mais de uma banca de 2\xaa inst\xe2ncia](/erros/uniplus.selecao.banca.etapa_com_mais_de_uma_banca_da_segunda_instancia) n\xe3o sai.","A mensagem da resposta cita a etapa pela posi\xe7\xe3o e a banca pelo nome do tipo e pela posi\xe7\xe3o dela: \\"A etapa na posi\xe7\xe3o *n* prev\xea a banca \'*tipo e posi\xe7\xe3o*\', com o papel \'Julga o recurso em 2\xaa inst\xe2ncia\', e nenhum recurso da etapa admite inst\xe2ncia superior. A banca de 2\xaa inst\xe2ncia da etapa julga s\xf3 os recursos dela; a do recurso da fase fica na pr\xf3pria fase. Retire essa banca, ou declare que um recurso da etapa admite inst\xe2ncia superior.\\""],"comoResolver":["Escolha um dos caminhos:","- retire a banca de 2\xaa inst\xe2ncia da etapa; se o recurso da fase admite inst\xe2ncia superior, a banca dele fica na pr\xf3pria fase;\\n- ou declare que um recurso da etapa admite inst\xe2ncia superior.","O painel de conformidade aponta a pend\xeancia antes da publica\xe7\xe3o, no item `cronograma_banca_da_segunda_instancia_com_recurso_para_julgar`."],"ondeAparece":["- Publica\xe7\xe3o inicial do processo seletivo\\n- Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Banca"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3bbcc2307827ee8c6dab135295710bb856847f61"}}')}}]);